package org.sleepwell.app;
import android.content.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.json.*;import org.junit.Test;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import static org.junit.Assert.*;
/** Existing CC0 whole PCM, exact production model/policy, no microphone and no assertion changes elsewhere. */
public final class SpeakFixtureEvaluationTest {
 private static final Map<String,String> HASHES=Map.of("speech-countdown","4a62ee7002290bce1555a3995c87fd6d0138343e54f767c418efd356e2765880","speech-balloon","6c31bfa246d0355c9d4d7af24dc7b5d1411aa6caa1474605958c1166cafcd30c","snoring-sorts","c7e95aed4687352e5dbd27148f521584e7224f7df7f1dddbb5875332dadce5a1","snoring-pencil","d53e9312fe9abd9ec6174d864b660ac38dc0edc792698087a99b774084ca68a1","music-archtects","093d73a4d71c99bada661076efd86bf5c9d81e04891a591b2c66000dde695894","crying-alucard","e65835a571cae08554c8cf3027a587274d8981249c362f028ac006a3c75dcb02");
 @Test public void unchangedSpeechRuleAcceptsTwoIndependentSourcesAndRejectsDeclaredDistractors()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext(),test=InstrumentationRegistry.getInstrumentation().getContext();assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",UiDevice.getInstance(InstrumentationRegistry.getInstrumentation()).executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(MicrophoneLease.occupied());JSONArray results=new JSONArray();try(InputStream in=c.getAssets().open("yamnet.tflite")){MessageDigest digest=MessageDigest.getInstance("SHA-256");byte[] bytes=new byte[8192];for(int n;(n=in.read(bytes))!=-1;)digest.update(bytes,0,n);assertEquals("10c95ea3eb9a7bb4cb8bddf6feb023250381008177ac162ce169694d05c317de",hex(digest.digest()));}try(YamnetClassifier model=new YamnetClassifier(c)){for(String name:List.of("speech-countdown","speech-balloon","snoring-sorts","snoring-pencil","music-archtects","crying-alucard")){byte[] data;try(InputStream in=test.getAssets().open("classifier-fixtures/"+name+".pcm")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];for(int size;(size=in.read(buffer))!=-1;){assertTrue(out.size()+size<=3*1024*1024);out.write(buffer,0,size);}data=out.toByteArray();}assertTrue(data.length<=3*1024*1024);SpeakRule rule=new SpeakRule();JSONArray windows=new JSONArray();boolean detected=false;float[] samples=new float[15600];for(int offset=0;offset+31200<=data.length;offset+=31200){for(int n=0;n<samples.length;n++)samples[n]=(short)((data[offset+n*2]&255)|(data[offset+n*2+1]<<8))/32768f;float[] scores=model.infer(samples);boolean accepted=rule.accept(scores);detected|=accepted;SoundAnalysis.Result chosen=SoundAnalysis.classify(scores);windows.put(new JSONObject().put("start_ms",offset*1000L/32000).put("production",chosen==null?"none":chosen.category).put("accepted",accepted));}boolean positive=name.startsWith("speech-");StringBuilder encoded=new StringBuilder();for(byte value:MessageDigest.getInstance("SHA-256").digest(data))encoded.append(String.format(Locale.ROOT,"%02x",value&255));String hash=encoded.toString();assertEquals(name,HASHES.get(name),hash);results.put(new JSONObject().put("fixture",name).put("sha256",hash).put("detected",detected).put("expected_speech",positive).put("windows",windows));}}
 File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());try(Writer writer=new OutputStreamWriter(new FileOutputStream(new File(folder,"speak-fixture-evaluation.json")),StandardCharsets.UTF_8)){writer.write(new JSONObject().put("model",YamnetClassifier.MODEL_ID).put("scope","Six existing CC0 source compatibility trials; no speaker identity, words, microphone or room accuracy proof; frozen laughter failure unchanged").put("fixtures",results).toString(2));}for(int n=0;n<results.length();n++){JSONObject row=results.getJSONObject(n);assertEquals(row.getString("fixture"),row.getBoolean("expected_speech"),row.getBoolean("detected"));}}
 private static String hex(byte[] bytes){StringBuilder value=new StringBuilder();for(byte b:bytes)value.append(String.format(Locale.ROOT,"%02x",b&255));return value.toString();}
}
